/* Client side logic for the python-editor (Pyodide) directive.
 *
 * The Pyodide runtime is loaded lazily from a CDN the first time the user
 * clicks Run. The URLs of the runtime are provided by an inline
 * configuration script (window.pyodideEditorConfig) generated by the
 * extension, so that the pyodide_version config value can be honoured.
 */
var pyodideEditor = (function() {
    "use strict";
    var state = { pyodide: null, loading: null, outputs: {} };

    var DEFAULT_CONFIG = {
        pyodideUrl: 'https://cdn.jsdelivr.net/pyodide/v314.0.7/full/pyodide.js',
        indexUrl: 'https://cdn.jsdelivr.net/pyodide/v314.0.7/full/'
    };

    function config() {
        return Object.assign({}, DEFAULT_CONFIG,
            window.pyodideEditorConfig || {});
    }

    function statusEl(container) {
        return container.querySelector('.pyodide-editor-status');
    }

    function setStatus(container, text, cls) {
        var el = statusEl(container);
        if (!el) return;
        el.textContent = text;
        el.className = 'pyodide-editor-status' + (cls ? ' ' + cls : '');
    }

    function outputEl(container) {
        return container.querySelector('.pyodide-editor-output');
    }

    function appendOutput(container, text) {
        var out = outputEl(container);
        if (out) out.textContent += text;
    }

    function loadScript(url) {
        return new Promise(function(resolve, reject) {
            var script = document.createElement('script');
            script.src = url;
            script.onload = resolve;
            script.onerror = function() { reject(new Error('Failed to load ' + url)); };
            document.head.appendChild(script);
        });
    }

    function getPyodide() {
        if (state.pyodide) return Promise.resolve(state.pyodide);
        if (!state.loading) {
            var cfg = config();
            state.loading = loadScript(cfg.pyodideUrl).then(function() {
                return window.loadPyodide({ indexURL: cfg.indexUrl });
            }).then(function(pyodide) {
                pyodide.setStdout({ batched: function(s) {
                    if (state.current) appendOutput(state.current, s + '\n');
                }});
                pyodide.setStderr({ batched: function(s) {
                    if (state.current) appendOutput(state.current, s + '\n');
                }});
                state.pyodide = pyodide;
                return pyodide;
            }).catch(function(err) {
                state.loading = null;
                throw err;
            });
        }
        return state.loading;
    }

    /* Pyodide's matplotlib backend appends figure canvases to document.body
     * when plt.show() is called. Patch plt.show so the canvases are inserted
     * into the output area of this editor instead. */
    function matplotlibPreamble(selector) {
        return [
            'try:',
            '    import matplotlib.pyplot as _ped_plt',
            '    from js import document as _ped_document',
            '    def _ped_show(*_args, **_kwargs):',
            '        _out = _ped_document.querySelector(' + JSON.stringify(selector) + ')',
            '        for _num in _ped_plt.get_fignums():',
            '            _canvas = _ped_plt.figure(_num).canvas',
            '            _canvas.draw() if hasattr(_canvas, "draw") else None',
            '            _out.appendChild(_canvas)',
            '        _ped_plt.close("all")',
            '    _ped_plt.show = _ped_show',
            'except ImportError:',
            '    pass',
        ].join('\n');
    }

    function getCode(container) {
        var textarea = container.querySelector('textarea.pyodide-editor-input');
        if (container._CodeMirrorEditor) {
            return container._CodeMirrorEditor.getValue();
        }
        return textarea ? textarea.value : '';
    }

    function initEditor(container) {
        if (container._pyodideEditorInitialized) return;
        container._pyodideEditorInitialized = true;
        var textarea = container.querySelector('textarea.pyodide-editor-input');
        if (!textarea) return;
        if (window.CodeMirror) {
            var cm = window.CodeMirror.fromTextArea(textarea, {
                mode: 'python',
                lineNumbers: true,
                matchBrackets: true,
                indentUnit: 4,
                theme: 'eclipse'
            });
            container._CodeMirrorEditor = cm;
        }
    }

    function initAll() {
        document.querySelectorAll('.pyodide-editor').forEach(initEditor);
        setStatusToReady();
    }

    function setStatusToReady() {
        document.querySelectorAll('.pyodide-editor').forEach(function(c) {
            var el = statusEl(c);
            if (el && !el.textContent) setStatus(c, 'Pyodide not loaded yet', '');
        });
    }

    function run(container) {
        var code = getCode(container);
        var runBtn = container.querySelector('.pyodide-editor-run');
        var out = outputEl(container);
        if (out) out.textContent = '';
        if (runBtn) runBtn.disabled = true;
        setStatus(container, 'Loading Pyodide...', '');
        getPyodide().then(function(pyodide) {
            setStatus(container, 'Running...', '');
            state.current = container;
            return pyodide.loadPackagesFromImports(code).then(function() {
                if (code.indexOf('matplotlib') !== -1) {
                    // Target the output area of *this* editor instance.
                    var selector = '#' + container.id + ' .pyodide-editor-output';
                    return pyodide.runPythonAsync(matplotlibPreamble(selector))
                        .then(function() {
                            return pyodide.runPythonAsync(code);
                        });
                }
                return pyodide.runPythonAsync(code);
            }).then(function(value) {
                state.current = null;
                if (value !== undefined) {
                    pyodide.globals.set('__pyodide_editor_result__', value);
                    return pyodide.runPythonAsync('repr(__pyodide_editor_result__)')
                        .then(function(repr) { appendOutput(container, repr + '\n'); });
                }
            });
        }).then(function() {
            setStatus(container, 'Ready', 'pyodide-status-ready');
        }).catch(function(err) {
            state.current = null;
            appendOutput(container, String(err) + '\n');
            setStatus(container, 'Error', 'pyodide-status-error');
        }).finally(function() {
            if (runBtn) runBtn.disabled = false;
        });
    }

    function reset(container) {
        var textarea = container.querySelector('textarea.pyodide-editor-input');
        var initial = textarea ? (textarea.getAttribute('data-initial-code') || '') : '';
        if (container._CodeMirrorEditor) {
            container._CodeMirrorEditor.setValue(initial);
        } else if (textarea) {
            textarea.value = initial;
        }
        var out = outputEl(container);
        if (out) out.textContent = '';
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }

    return {
        run: function(btn) { run(btn.closest('.pyodide-editor')); },
        reset: function(btn) { reset(btn.closest('.pyodide-editor')); }
    };
})();
